from itertools import product

def solve_di_equation():
    solutions = []
    # Coefficients d_i range from -2 to 2
    d_range = range(-2, 3)

    # Iterate through all combinations of d1, d2, d3, d4
    for d1, d2, d3, d4 in product(d_range, repeat=4):
        if d1 == 0 and d2 == 0 and d3 == 0 and d4 == 0:
            continue

        if d1 + 2*d2 + 4*d3 + 8*d4 == 0:
            solutions.append((d1, d2, d3, d4))

    return solutions

solutions = solve_di_equation()
print(f"Found {len(solutions)} non-trivial solutions.")
if solutions:
    print("Example solution (d1, d2, d3, d4):", solutions[0])
else:
    print("No solutions found.")

